import{z as d,x as A,o as r,c as B,q as l,j as n,D as e,d as i,s as E,S as s,b as t}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"在线算法与竞争比","description":"","frontmatter":{"title":"在线算法与竞争比","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/competitive-ratio.md","filePath":"cs/competitive-ratio.md","lastUpdated":1791063341000}'),p={name:"cs/competitive-ratio.md"};function m(h,a,c,P,u,T){const o=A("Mermaid");return r(),B("div",null,[a[2]||(a[2]=l('<h1 id="在线算法与竞争比" tabindex="-1">在线算法与竞争比 <a class="header-anchor" href="#在线算法与竞争比" aria-label="Permalink to &quot;在线算法与竞争比&quot;">​</a></h1><div class="epigraph"><p>输入一个个到来、决策不可悔；竞争比是算法代价与事后最优的最坏比，对手可自适应。</p><footer>—— 据 Sleator and Tarjan, Amortized Efficiency of List Update and Paging Rules, 1985；Borodin and El-Yaniv, Online Computation and Competitive Analysis 整理</footer></div><p>上一课<a href="/cs/random-walk-mixing">随机游走</a>假定图已知；在线算法连输入都是逐步揭示的，决策不可悔。势能法你已会，缺口是竞争比的定义：\\(\\mathrm{ALG}\\le\\rho\\cdot\\mathrm{OPT}+O(1)\\)，取每个序列上的最坏比值。不重写 Karger。后课分页、租买、秘书都是本课定义的实例；不把限价簿当输入模型——那是 quant 栏的对象。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>同一问题给两方做：离线 OPT 看见完整序列后从容规划；在线第 \\(t\\) 步只看见前 \\(t\\) 个请求，却必须当场付出代价。差距可以很大：确定性算法下，对手总能构造专打弱点的序列压到下界；换成随机算法、对手 oblivious（出题前不知硬币结果），界可以更好。证明上界的主力是势函数：取 \\(\\Phi\\ge 0\\)、初值 \\(0\\)，使每步满足「实际代价 \\(+\\Delta\\Phi\\le\\rho\\times\\) OPT 同步一步的代价」，求和后势能项首尾消去，只剩 \\(\\mathrm{ALG}\\le\\rho\\cdot\\mathrm{OPT}\\)。</p><p>缺口是定义，不是具体分页（下一课）。</p><p><span class="marginnote">直觉类比：在线算法像只能看当前这一手的棋手；离线 OPT 像开了天眼、看完整盘对局才从容落子。竞争比回答的是：不开天眼的选手，最坏情况下要比开了天眼的选手多付出几倍代价。</span></p><h3 id="不是平均情形" tabindex="-1">不是平均情形 <a class="header-anchor" href="#不是平均情形" aria-label="Permalink to &quot;不是平均情形&quot;">​</a></h3><p>竞争比取遍所有序列的最坏值；平均输入是另一套模型，结论互不推出。不要把「实践还行」当 \\(\\rho\\)——竞争比是保证，不是口碑。</p><p><span class="marginnote">Sleator–Tarjan 1985 列表更新与分页。Borodin–El-Yaniv 书。后课分页、ski-rental、秘书。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>次序：先写离线最优解的结构（它定义分母），再设计在线策略、用势或不变量证上界，最后给下界——构造对手策略，证明任何在线算法都逃不过某个 \\(\\rho_0\\)。上下界夹住，才谈得上这个竞争比是正确价格。随机算法必须写清对手模型。</p><p><span class="marginnote">术语翻译：oblivious（非自适应）对手，就是「出题前不知道你掷硬币结果」的出题人——题目与你的运气相互独立；自适应对手则边看你的每步动作边改题，能压得更狠。所以谈随机算法的竞争比，必须先声明对手是哪一种。</span></p>',13)),(r(),n(s,null,{default:e(()=>[E(o,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E5%BA%8F%E5%88%97%E9%80%90%E9%A1%B9%22%5D%20--%3E%20ON%5B%22%E4%B8%8D%E5%8F%AF%E6%82%94%E5%86%B3%E7%AD%96%22%5D%0A%20%20ON%20--%3E%20RHO%5B%22ALG%20%E2%89%A4%20%CF%81%20OPT%20%2B%20O(1)%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("p",null,"右边允许加性常数 \\(O(1)\\)：OPT 极小的序列上比值无界，加常数让定义良态。",-1)),a[4]||(a[4]=t("h2",{id:"机制",tabindex:"-1"},[i("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=t("p",null,"势函数的直觉是把「未来要还的债」记在数据结构状态上：状态越懒散（如缓存里留着迟早要换出的页），\\(\\Phi\\) 越高，当前多付的摊还代价就是提前还债；初值 \\(0\\)、终值非负，求和时 \\(\\Phi\\) 首尾相消，剩下的恰是摊还不等式。对手论证后课专讲。与近似比区分：近似算法拿到完整输入、受限于多项式时间，输给的是算力；在线算法想算多久都行，输给的是信息缺失。与流算法区分：流模型只限内存、允许读完全部输入后再输出，在线必须在请求到达的当下承诺行动。",-1)),(r(),n(s,null,{default:e(()=>[E(o,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20STEP%5B%22%E4%B8%80%E4%B8%AA%E8%AF%B7%E6%B1%82%E6%AD%A5%22%5D%20--%3E%20PAY%5B%22%E5%9C%A8%E7%BA%BF%E5%AE%9E%E9%99%85%E4%BB%A3%E4%BB%B7%22%5D%0A%20%20STEP%20--%3E%20DPHI%5B%22%E5%8A%BF%E8%83%BD%E5%8F%98%E5%8C%96%20%CE%94%CE%A6%22%5D%0A%20%20PAY%20--%3E%20AM%5B%22%E5%AE%9E%E9%99%85%E4%BB%A3%E4%BB%B7%20%2B%20%CE%94%CE%A6%22%5D%0A%20%20DPHI%20--%3E%20AM%0A%20%20AM%20--%3E%20INEQ%5B%22%E6%AF%8F%E6%AD%A5%20%E2%89%A4%20%CF%81%20%C3%97%20OPT%20%E5%90%8C%E6%AD%A5%E4%BB%A3%E4%BB%B7%22%5D%0A%20%20INEQ%20--%3E%20SUM%5B%22%E5%AF%B9%E6%95%B4%E4%B8%AA%E5%BA%8F%E5%88%97%E6%B1%82%E5%92%8C%22%5D%0A%20%20SUM%20--%3E%20CANCEL%5B%22%CE%A6%20%E5%88%9D%E5%80%BC%200%20%E4%B8%94%E9%9D%9E%E8%B4%9F%2C%20%E9%A6%96%E5%B0%BE%E7%9B%B8%E6%B6%88%22%5D%0A%20%20CANCEL%20--%3E%20CONC%5B%22%E5%BE%97%20ALG%20%E2%89%A4%20%CF%81%C2%B7OPT%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<p><span class="marginnote">常见误区：把 \\(\\rho=2\\) 理解成「每次都吃亏一倍」。它的准确含义是：无论对手出什么序列，你的总代价不会超过最优的两倍加常数——有些序列上恰好差满两倍，多数输入可能远好于此。竞争比是最坏情况保证，不是平均预期。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写全部 k-server 理论，也不写预测增强在线——那里 \\(\\rho\\) 变成预测误差的函数。后课默认：谈在线算法质量就用竞争比。下一课页面置换。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>竞争比 = 最坏 ALG/OPT。</li><li>势函数是主证法。</li><li>与离线近似、流模型不同。</li><li>出处：Sleator and Tarjan, 1985。</li></ul>',5))])}const f=d(p,[["render",m]]);export{D as __pageData,f as default};
